                    warnings.append(f"{p.symbol}: requested end close unfilled due to zero recorded volume; remains OPEN")
                    continue
                a.close(p, a.marks[p.symbol], config.end_ms, config, "END_OF_TEST_EXPLICIT", (config.end_ms, config.end_ms))
