"""Bounded data-only language. Never eval/exec/compile/import user text.

The evaluator is trusted code; untrusted definitions can only select these
finite operators. All observations are completed bars. No files/network/loops.
"""
from dataclasses import dataclass
from decimal import Decimal

from .common import canonical, decimal, digest, integer
from .errors import ValidationError
from .models import Signal

FIELDS = {"open", "high", "low", "close", "volume"}
COMPARE = {"gt", "gte", "lt", "lte", "eq", "cross_above", "cross_below"}


def validate(raw):
    allowed = {"schema_version", "kind", "name", "long", "short", "exit_long", "exit_short", "stop", "target_fraction", "management"}
    if not isinstance(raw, dict) or set(raw)-allowed or raw.get("kind") != "STUDIO_RULES" or type(raw.get("schema_version")) is not int or raw["schema_version"] != 1:
        raise ValidationError("expected STUDIO_RULES schema_version 1; Python/JavaScript and unknown fields are rejected")
    if len(canonical(raw).encode()) > 12000:
        raise ValidationError("strategy definition exceeds 12KiB")
    name = raw.get("name")
    if not isinstance(name, str) or not 1 <= len(name) <= 80 or any(ord(c)<32 for c in name):
        raise ValidationError("name requires 1–80 printable characters")
    count = 0
    def node(x, boolean=False, depth=0):
        nonlocal count
        count += 1
        if count > 128 or depth > 8:
            raise ValidationError("strategy expression budget: 128 nodes / depth 8")
        if boolean and type(x) is bool:
            return
        if not boolean and not isinstance(x, list):
            decimal(x, "expression literal", "-1000000000", "1000000000"); return
        if not isinstance(x, list) or not x or not isinstance(x[0], str):
            raise ValidationError("invalid structured expression")
        op, args = x[0], x[1:]
        if boolean:
            if op in {"and", "or"} and 1 <= len(args) <= 8:
                for a in args: node(a, True, depth+1)
            elif op == "not" and len(args) == 1: node(args[0], True, depth+1)
            elif op in COMPARE and len(args) == 2:
                for a in args: node(a, False, depth+1)
            else: raise ValidationError("unsupported condition or arity")
        elif op in FIELDS and len(args) == 1:
            integer(args[0], "bar offset", 0, 200)
        elif op in {"sma", "atr"} and len(args) == 2:
            integer(args[0], "indicator period", 2, 200); integer(args[1], "bar offset", 0, 200)
        elif op in {"add", "sub", "mul", "div"} and len(args) == 2:
            for a in args: node(a, False, depth+1)
        else: raise ValidationError("unsupported numeric operator; no attributes, calls or executable code")
    for name in ("long", "short", "exit_long", "exit_short"):
        node(raw.get(name, False), True)
    stop = raw.get("stop")
    if not isinstance(stop, dict) or stop.get("type") not in {"fixed", "atr"}:
        raise ValidationError("stop must be fixed or atr")
    if stop["type"] == "fixed" and set(stop) == {"type", "fraction"}:
        decimal(stop["fraction"], "stop fraction", ".0001", ".5")
    elif stop["type"] == "atr" and set(stop) == {"type", "period", "multiple"}:
        integer(stop["period"], "ATR period", 2, 200); decimal(stop["multiple"], "ATR multiple", ".1", "20")
    else: raise ValidationError("invalid stop fields")
    target = raw.get("target_fraction")
    if target is not None: decimal(target, "target fraction", ".0001", ".99")
    m = raw.get("management", {})
    if not isinstance(m, dict) or set(m)-{"trailing", "partials", "max_hold_bars", "breakeven_at"}:
        raise ValidationError("unsupported position-management fields")
    if "max_hold_bars" in m: integer(m["max_hold_bars"], "max hold bars", 1, 2102400)
    if "breakeven_at" in m: decimal(m["breakeven_at"], "breakeven activation", ".0001", "10")
    if "trailing" in m:
        t = m["trailing"]
        if not isinstance(t, dict) or set(t) != {"activate_fraction", "distance_fraction"}: raise ValidationError("trailing requires activate_fraction/distance_fraction")
        decimal(t["activate_fraction"], "trail activation", ".0001", "10")
        decimal(t["distance_fraction"], "trail distance", ".0001", ".99")
    parts = m.get("partials", [])
    if not isinstance(parts, list) or len(parts)>4: raise ValidationError("at most four partial exits")
    total = Decimal(0); previous = Decimal(0)
    for p in parts:
        if not isinstance(p, dict) or set(p)!={"profit_fraction", "close_fraction"}: raise ValidationError("invalid partial exit")
        level = decimal(p["profit_fraction"], "partial threshold", ".0001", "10")
        if level <= previous: raise ValidationError("partial thresholds must strictly increase")
        previous = level; total += decimal(p["close_fraction"], "partial original quantity fraction", ".0001", ".99")
    if total >= 1: raise ValidationError("partial fractions of ORIGINAL quantity must total less than 1")
    # Copy through JSON, disallow mutable aliases and non-JSON objects.
    import json
    value = json.loads(canonical(raw))
    if warmup(value)>501: raise ValidationError("warm-up exceeds 501 completed bars")
    return value


def warmup(raw):
    def walk(x):
        if not isinstance(x, list) or not x: return 1
        if x[0] in FIELDS: return x[1]+1
        if x[0] in {"sma", "atr"}: return x[1]+x[2]+1
        return max([1]+[walk(a) for a in x[1:]])+(1 if x[0] in {"cross_above", "cross_below"} else 0)
    return max([walk(raw.get(k)) for k in ("long", "short", "exit_long", "exit_short")]+[raw["stop"].get("period", 0)+1])


def number(expr, bars, shift=0):
    if not isinstance(expr, list): return Decimal(str(expr))
    op, args = expr[0], expr[1:]
    if op in FIELDS: return getattr(bars[-1-args[0]-shift], op)
    if op in {"sma", "atr"}:
        period, offset = args; end = len(bars)-offset-shift
        if op == "sma": return sum((b.close for b in bars[end-period:end]), Decimal(0))/period
        return sum((max(bars[i].high-bars[i].low, abs(bars[i].high-bars[i-1].close), abs(bars[i].low-bars[i-1].close)) for i in range(end-period, end)), Decimal(0))/period
    a, b = (number(x, bars, shift) for x in args)
    if op == "add": return a+b
    if op == "sub": return a-b
    if op == "mul": return a*b
    if b == 0: raise ValidationError("strategy expression divides by zero; no successful result accepted")
    return a/b


def condition(expr, bars):
    if type(expr) is bool: return expr
    op, args = expr[0], expr[1:]
    if op == "and": return all(condition(a, bars) for a in args)
    if op == "or": return any(condition(a, bars) for a in args)
    if op == "not": return not condition(args[0], bars)
    a,b = (number(x,bars) for x in args)
    if op in {"cross_above", "cross_below"}:
        pa,pb = (number(x,bars,1) for x in args)
        return (pa<=pb and a>b) if op=="cross_above" else (pa>=pb and a<b)
    return {"gt":a>b, "gte":a>=b, "lt":a<b, "lte":a<=b, "eq":a==b}[op]


@dataclass(frozen=True)
class StudioStrategy:
    definition: dict
    content_hash: str
    managed: bool = True

    @property
    def warmup_bars(self): return warmup(self.definition)
    @property
    def version_id(self): return "STUDIO_RULES_"+self.content_hash

    def evaluate(self, history):
        d=self.definition; b=history[-1]; stop=d["stop"]
        fraction = Decimal(str(stop["fraction"])) if stop["type"]=="fixed" else number(["atr",stop["period"],0],history)*Decimal(str(stop["multiple"]))/b.close
        if not Decimal('.0001') <= fraction <= Decimal('.5'):
            return Signal(b.symbol,b.end_ms,"NO_SIGNAL","ATR_STOP_OUTSIDE_SUPPORTED_BOUNDS",Decimal('.0001'))
        long=condition(d.get("long",False),history); short=condition(d.get("short",False),history)
        side = "NO_SIGNAL" if long==short else ("LONG" if long else "SHORT")
        return Signal(b.symbol,b.end_ms,side,"CONFLICTING_DIRECTIONS" if long and short else "STRUCTURED_RULE",fraction,
                      None if d.get("target_fraction") is None else Decimal(str(d["target_fraction"])))


def build(raw):
    value=validate(raw)
    return StudioStrategy(value,digest(value))


EXAMPLE = {"schema_version":1,"kind":"STUDIO_RULES","name":"Editable SMA crossover example (not private HKS)",
           "long":["cross_above",["sma",5,0],["sma",20,0]],"short":False,
           "exit_long":["cross_below",["sma",5,0],["sma",20,0]],
           "stop":{"type":"fixed","fraction":"0.02"},"target_fraction":None,
           "management":{"trailing":{"activate_fraction":"0.03","distance_fraction":"0.015"},
                         "partials":[{"profit_fraction":"0.04","close_fraction":"0.25"}],"max_hold_bars":180}}

browser_adapter.py:
"""Browser-only IO seam. V4 Decimal, validation and accounting remain untouched.

The JavaScript function is supplied by the trusted financial Web Worker. User
Python is in another interpreter in an opaque-origin worker and has no reference
to this interpreter, its memory, source, storage, or result objects.
"""
import json, sys, types, time
from pathlib import Path

shim=types.ModuleType('backtester.python_sandbox')
class UnusedRPC:
    def __init__(self,*args):raise RuntimeError('No host/subprocess sandbox in browser')
shim.RPC=UnusedRPC
sys.modules['backtester.python_sandbox']=shim
from backtester.python_runtime import PythonRuntime
from backtester.python_definition import build
from backtester.data import load_dataset
from backtester.config import RunConfig
from backtester.simulation import simulate
from backtester.common import canonical, timestamp
from browser_stream import chunks
from backtester.browser_context import CompletedContext, requirements, CONTRACT

class BrowserRPC:
    def __init__(self, context=None):
        self.context=context;self.last_exit=None
        self.profile={k:0 for k in ('contextMs','frameEncodingMs','rpcWaitMs','decisionDecodeMs','calls')}
    def call(self,frame):
        import js
        started=time.perf_counter()
        if self.context is not None:
            last=frame['bars'][-1]
            frame={**frame,'contexts':self.context.at(frame['symbol'],last['open_ms']+last['interval_ms']),
                   'last_exit':self.last_exit}
        encoded_at=time.perf_counter();self.profile['contextMs']+=(encoded_at-started)*1000
        raw=canonical(frame)
        if len(raw.encode())>512*1024:raise ValueError('512KiB completed-context frame bound exceeded')
        sent_at=time.perf_counter();self.profile['frameEncodingMs']+=(sent_at-encoded_at)*1000
        reply=str(js.strategy_call(raw));received_at=time.perf_counter()
        self.profile['rpcWaitMs']+=(received_at-sent_at)*1000
        answer=json.loads(reply)
        self.profile['decisionDecodeMs']+=(time.perf_counter()-received_at)*1000;self.profile['calls']+=1
        if 'error' in answer:raise ValueError(answer['error'])
        return answer['decision']

class BrowserRuntime(PythonRuntime):
    def __init__(self,definition,dataset=None,start_ms=None):
        spec=build(definition)
        self.definition=spec.definition;self.content_hash=spec.content_hash
        self.version_id=spec.version_id;self.warmup_bars=spec.warmup_bars
        requested,needed=requirements(spec.definition,spec.warmup_bars)
        if requested and (dataset is None or start_ms is None):raise ValueError('Declared multi-timeframe context needs its verified dataset and UTC start')
        context=CompletedContext(dataset,requested,needed,start_ms) if requested else None
        self.rpc=BrowserRPC(context);self.previous={};self.signals={}
        self._closed_offsets={};self._last_exits={}

    def after_close(self,account,bar,history):
        # Read-only execution evidence, including positions stopped within their
        # first minute. Rebuild from the restored ledger on a fresh runtime;
        # never infer exits from an absence of positions or mutate the ledger.
        if getattr(self.rpc,'context',None) is not None:
            key=id(account);offset=self._closed_offsets.get(key,0)
            for row in account.closed[offset:]:
                self._last_exits[key,row['symbol']]={k:row[k] for k in
                    ('exit_ms','fill_window_start_ms','fill_window_end_ms','exit_reason')}
            self._closed_offsets[key]=len(account.closed)
            self.rpc.last_exit=self._last_exits.get((key,bar.symbol))
        return super().after_close(account,bar,history)

def run_browser(raw):
    try:
        bundle=json.loads(raw);root=Path('/input');root.mkdir(exist_ok=True)
        manifest=bundle['manifest'];files=bundle['files']
        if not isinstance(files,dict) or len(files)>20:raise ValueError('1–20 input files required')
        if sum(len(x.encode()) for x in files.values())>32*1024**2:raise ValueError('32MiB proof input bound')
        for name,value in files.items():
            if Path(name).name!=name or not name.endswith('.csv'):raise ValueError('unsafe candle filename')
            (root/name).write_text(value)
        (root/'manifest.json').write_text(canonical(manifest))
        ds=load_dataset(root,as_of_ms=timestamp('2026-10-17T00:00:00Z'))
        config=RunConfig.from_dict(bundle['config'])
        result=simulate(ds,BrowserRuntime(bundle['definition'],ds,config.start_ms),config)
        return canonical({'ok':True,'result':result})
    except Exception as e:
        return canonical({'ok':False,'error':str(e)[:700]})

_stream = None
_runtime = None
_stream_profile = {}
def start_stream(raw, checkpoint='null'):
    global _stream,_runtime,_stream_profile
    started=time.perf_counter()
    bundle=json.loads(raw);root=Path('/input');root.mkdir(exist_ok=True)
    manifest=bundle['manifest'];files=bundle['files']
    if not isinstance(files,dict) or not 1<=len(files)<=20:raise ValueError('1–20 input files required')
    if sum(len(x.encode()) for x in files.values())>32*1024**2:raise ValueError('32MiB input bound; requested range is not silently shortened')
    for name,value in files.items():
        if Path(name).name!=name or not name.endswith('.csv'):raise ValueError('unsafe candle filename')
        (root/name).write_text(value)
    (root/'manifest.json').write_text(canonical(manifest))
    dataset=load_dataset(root,as_of_ms=timestamp('2026-10-17T00:00:00Z'))
    config=RunConfig.from_dict(bundle['config'])
    parsed_at=time.perf_counter()
    _runtime=BrowserRuntime(bundle['definition'],dataset,config.start_ms)
    restored=json.loads(checkpoint)
    _stream=chunks(dataset,_runtime,config,restored,bundle.get('checkpoint_every',120))
    restored_calls=0
    if restored:
        from browser_stream import decode
        restored_calls=sum(x['evaluations'] for x in decode(restored['state'])['counts'].values())
    _stream_profile={}
    return canonical({'loaded_candles':sum(len(x) for x in dataset.candles.values()),
                      'dataset_hash':dataset.content_hash,'next_ms':restored['next_ms'] if restored else config.start_ms,
                      'restored_calls':restored_calls,'inputValidationMs':(parsed_at-started)*1000,
                      'contextInitializationMs':(time.perf_counter()-parsed_at)*1000})

def next_stream():
    global _stream_profile
    started=time.perf_counter()
    value=next(_stream)
    advanced_at=time.perf_counter();view_ms=0
    if value['kind']=='DONE':
        from backtester.reports import build_reports
        from backtester.studio_metrics import position_performance
        from decimal import Decimal, localcontext
        result=value['result']
        with localcontext() as ctx:
            ctx.prec=34
            current={name:Decimal(row['initial_capital']) for name,row in result['accounts'].items()}
            points={}
            for row in result['equity_curve']:
                current[row['account']]=Decimal(row['equity'])
                points[row['timestamp_ms']]=sum(current.values(),Decimal(0))
            rows=list(points.items());step=max(1,(len(rows)+598)//599)
            selected=rows[::step]
            if rows and (not selected or selected[-1]!=rows[-1]):selected.append(rows[-1])
            value['view']={'reports':build_reports(result),
                           'position_performance':position_performance(result),
                           'warnings':[('Browser trusted-code worker execution, NOT an OS container. Legacy raw financial result/hash retained for parity; no exchange fills certified.' if w.startswith('Python runs in a separate secret-free OS container.') else w) for w in result['warnings']],
                           'chart_sample':[{'timestamp_ms':ts,'equity':str(eq)} for ts,eq in selected]}
        view_ms=(time.perf_counter()-advanced_at)*1000
    serializing_at=time.perf_counter();raw=serialize_event(value)
    _stream_profile={'advanceMs':(advanced_at-started)*1000,'viewMs':view_ms,
                     'serializationMs':(time.perf_counter()-serializing_at)*1000,
                     'financialCaptureMs':value.get('capture_ms',0),'callbacks':dict(_runtime.rpc.profile)}
    return raw

def serialize_event(value):
    # Checkpoints are already typed JSON; DONE results/reports have already
    # passed their pinned primitives() conversion. Walking this entire growing
    # equity history again adds no validation or financial meaning. Keep the
    # identical canonical JSON options, reject unsupported/non-finite values,
    # and prove byte equality against canonical() in regression tests.
    return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True,allow_nan=False)

def stream_profile():
    return canonical(_stream_profile)

def validate_browser(raw):
    spec=build(json.loads(raw))
    requested,needed=requirements(spec.definition,spec.warmup_bars)
    result={'definition':spec.definition,'version_id':spec.version_id,
            'content_hash':spec.content_hash,'warmup_bars':spec.warmup_bars}
    if requested:result.update(context_timeframes=requested,input_warmup_bars=needed,context_contract=CONTRACT)
    return canonical(result)

browser_stream.py:
"""Checkpoint orchestration around the pinned V4 loop, without financial edits.

Only loop scheduling changes: yield after a completed global timestamp, and
restore explicitly typed state before selecting the next chronological candle.
Financial checkpoint data is JSON, never pickle/code. Strategy snapshots are
opaque and restored only in the isolated, trusted-code strategy worker.
"""
import ast
import inspect
import json
import math
import time
from collections import deque
from dataclasses import fields
from decimal import Decimal, localcontext

from backtester import simulation
from backtester.models import Candle, Position, Signal
from backtester.python_definition import PythonSignal
from backtester.portfolio import Account
from backtester.studio_management import ManagedAccount

TYPES = {t.__name__: t for t in (Candle, Position, Signal, PythonSignal, Account, ManagedAccount)}
STATE_NAMES = ('accounts', 'histories', 'pending', 'seen', 'last_bars', 'journal',
               'equity', 'warnings', 'counts', 'position_count')
MAX_CHECKPOINT = 64 * 1024 * 1024

def encode(value):
    if value is None or type(value) in (str, int, bool):
        return value
    if isinstance(value, Decimal):
        return {'@': 'decimal', 'v': str(value)}
    if type(value) is list:
        return [encode(x) for x in value]
    if type(value) is dict:
        if any(type(k) is not str for k in value):
            raise ValueError('checkpoint dictionary keys must be strings')
        return {'@': 'dict', 'v': [[k, encode(v)] for k, v in value.items()]}
    if type(value) in (tuple, set, deque):
        return {'@': type(value).__name__, 'v': [encode(x) for x in value],
                'maxlen': value.maxlen if isinstance(value, deque) else None}
    name = type(value).__name__
    if TYPES.get(name) is not type(value):
        raise ValueError('unsupported financial checkpoint type: ' + name)
    return {'@': name, 'v': encode(vars(value))}

def decode(value, depth=0):
    if depth > 60:
        raise ValueError('checkpoint nesting limit')
    if value is None or type(value) in (str, int, bool):
        return value
    if type(value) is list:
        return [decode(x, depth + 1) for x in value]
    if type(value) is not dict or set(value) - {'@', 'v', 'maxlen'}:
        raise ValueError('invalid typed checkpoint')
    kind, raw = value.get('@'), value.get('v')
    dec = lambda v: decode(v, depth + 1)
    if kind == 'decimal':
        d = Decimal(raw)
        if not d.is_finite():
            raise ValueError('non-finite checkpoint decimal')
        return d
    if kind == 'dict':
        if any(type(k) is not str for k, _ in raw) or len({k for k, _ in raw}) != len(raw):
            raise ValueError('invalid checkpoint dictionary')
        return {k: dec(v) for k, v in raw}
    if kind in ('tuple', 'set', 'deque'):
        values = [dec(x) for x in raw]
        if kind == 'deque':
            if type(value.get('maxlen')) is not int or not 1 <= value['maxlen'] <= 501:
                raise ValueError('invalid history length')
            return deque(values, maxlen=value['maxlen'])
        return tuple(values) if kind == 'tuple' else set(values)
    cls = TYPES.get(kind)
    if cls is None:
        raise ValueError('unrecognized checkpoint type')
    attrs = dec(raw)
    obj = cls(**{f.name: attrs[f.name] for f in fields(cls)})
    for name, v in attrs.items():
        if name.startswith('__'):
            raise ValueError('unsafe checkpoint attribute')
        object.__setattr__(obj, name, v)
    return obj

def capture(scope, next_ms):
    result = {'schema': 1, 'next_ms': next_ms,
              'state': encode({name: scope[name] for name in STATE_NAMES}),
              'runtime': encode({'previous': scope['strategy'].previous,
                                 'signals': scope['strategy'].signals})}
    raw = json.dumps(result, separators=(',', ':'))
    if len(raw.encode()) > MAX_CHECKPOINT:
        raise ValueError('64 MiB financial checkpoint bound exceeded; no truncated checkpoint')
    return result

def checkpoint_event(scope, next_ms):
    started = time.monotonic()
    snapshot = capture(scope, next_ms)
    return {'kind': 'CHECKPOINT', 'snapshot': snapshot,
            'capture_ms': (time.monotonic() - started) * 1000}

def restore(snapshot, strategy):
    if snapshot.get('schema') != 1 or type(snapshot.get('next_ms')) is not int:
        raise ValueError('unsupported checkpoint schema')
    state = decode(snapshot['state'])
    if set(state) != set(STATE_NAMES):
        raise ValueError('incomplete financial checkpoint')
    runtime = decode(snapshot['runtime'])
    strategy.previous, strategy.signals = runtime['previous'], runtime['signals']
    return state

def make_iterator():
    """Mechanical AST edits are tested against the entire pinned result object."""
    tree = ast.parse(inspect.getsource(simulation._simulate))
    fn = tree.body[0]
    fn.name = '_checkpoint_iterator'
    fn.args.kwonlyargs += [ast.arg(arg=n) for n in ('resume','checkpoint_every','work_steps','yield_seconds')]
    fn.args.kw_defaults += [ast.Constant(None), ast.Constant(120), ast.Constant(240), ast.Constant(1.0)]
    loop = next(n for n in fn.body if isinstance(n, ast.For) and isinstance(n.target, ast.Tuple)
                and [getattr(x, 'id', None) for x in n.target.elts] == ['ts', 'values'])
    before_streams = next(i for i, n in enumerate(fn.body) if isinstance(n, ast.Assign)
                          and any(isinstance(t, ast.Name) and t.id == 'streams' for t in n.targets))
    restore_src = '''
if resume is not None:
    _restored = restore(resume, strategy)
    accounts = _restored['accounts']
    histories = _restored['histories']
    pending = _restored['pending']
    seen = _restored['seen']
    last_bars = _restored['last_bars']
    journal = _restored['journal']
    equity = _restored['equity']
    warnings = _restored['warnings']
    counts = _restored['counts']
    position_count = _restored['position_count']
    warmup_start = resume['next_ms']
_completed = 0
_work = 0
_first_checkpoint = resume is not None
_chunk_started = time.monotonic()
'''
    fn.body[before_streams:before_streams] = ast.parse(restore_src).body
    loop.body += ast.parse('''
_completed += 1
_work += len(bars)
_work_boundary = _work >= work_steps or time.monotonic() - _chunk_started >= yield_seconds
if _completed % checkpoint_every == 0 or _work_boundary:
    if _completed % checkpoint_every == 0 or not _first_checkpoint:
        yield checkpoint_event(locals(), end)
        _first_checkpoint = True
    else:
        yield {'kind': 'PROGRESS', 'next_ms': end}
    _work = 0
    started = time.monotonic()
    _chunk_started = started
''').body
    # A generator return retains the original result (including its result hash).
    ast.fix_missing_locations(tree)
    namespace = dict(vars(simulation), checkpoint_event=checkpoint_event, restore=restore)
    exec(compile(tree, '<pinned-v4-checkpoint-scheduling>', 'exec'), namespace)
    return namespace[fn.name]

ITERATE = make_iterator()

def chunks(dataset, strategy, config, resume=None, checkpoint_every=120,
           work_steps=240, yield_seconds=1.0):
    if type(checkpoint_every) is not int or not 1 <= checkpoint_every <= 1440:
        raise ValueError('checkpoint interval must be 1–1440 timestamps')
    if type(work_steps) is not int or not 1 <= work_steps <= 10000:
        raise ValueError('work limit must be 1–10000 symbol-candle steps')
    if type(yield_seconds) not in (int,float) or not math.isfinite(yield_seconds) or not 0 < yield_seconds <= 5:
        raise ValueError('work-time target must be positive and at most five seconds')
    # Keeping this context inside a generator prevents JS scheduling from
    # changing Decimal precision between chunks.
    with localcontext() as context:
        context.prec = 34
        it = ITERATE(dataset, strategy, config, None, resume=resume,
                     checkpoint_every=checkpoint_every,work_steps=work_steps,
                     yield_seconds=yield_seconds)
        while True:
            try:
                yield next(it)
            except StopIteration as done:
                yield {'kind': 'DONE', 'result': done.value}
                return
